// #561052 (c36332c5df5b97b7e9561052) — шаг 1 «פרטים כלליים» как Figma 866:9930:
//  AC1 «מטרת השיחה», «תנאי סיום שהוגדר מראש», «התוצאה הרצויה» — высота 52px, как остальные поля
//      (пустые и с текстом в одну строку); длинный текст — поле растёт, текст не обрезается (принято 04.11);
//  AC2 линия 1px rgba(255,255,255,.08) перед группами «משך ותנאי סיום» и «היעד של השיחה».
// Роль business. Новый черновик НЕ сохраняется (только ввод на /simulations/new?start=scratch, без «הבא») → @prod-safe.
// Экран бизнеса — только десктоп (1440).
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { field, currentStep } from '../support/simulation-editor';

const TAG = '#561052 · #c36332c5df5b97b7e9561052';
const FIELDS = ['call_goal', 'end_conditions', 'desired_outcome'] as const;
const SHORT: Record<(typeof FIELDS)[number], string> = {
  call_goal: 'לקבוע פגישת ייעוץ',
  end_conditions: 'הלקוח מנתק',
  desired_outcome: 'פגישה נקבעה',
};
const LONG = 'QA-AUTO טקסט ארוך מאוד לבדיקת גובה השדה '.repeat(8).trim();

async function heights(page: Page) {
  const out: Record<string, { h: number; clipped: boolean }> = {};
  for (const f of FIELDS) {
    out[f] = await field(page, f).evaluate((el: HTMLElement) => ({
      h: Math.round(el.getBoundingClientRect().height),
      clipped: el.scrollHeight > el.clientHeight + 1,
    }));
  }
  return out;
}

/** Горизонтальная линия у legend группы: border-top легенды/fieldset или ::before/::after высотой 1px. */
async function dividerOf(page: Page, title: string) {
  const legend = page.locator('fieldset > legend').filter({ hasText: title });
  await expect(legend, `группа «${title}»`).toHaveCount(1);
  return legend.evaluate((lg: HTMLElement) => {
    const found: { where: string; px: number; color: string }[] = [];
    const check = (where: string, cs: CSSStyleDeclaration) => {
      for (const side of ['Top', 'Bottom'] as const) {
        const w = parseFloat(cs[`border${side}Width` as 'borderTopWidth']);
        const st = cs[`border${side}Style` as 'borderTopStyle'];
        if (w > 0 && st !== 'none') found.push({ where: `${where} border-${side}`, px: w, color: cs[`border${side}Color` as 'borderTopColor'] });
      }
      const h = parseFloat(cs.height);
      if (where.includes('::') && cs.content !== 'none' && h > 0 && h <= 2 && cs.backgroundColor !== 'rgba(0, 0, 0, 0)') {
        found.push({ where: `${where} background`, px: h, color: cs.backgroundColor });
      }
    };
    for (const el of [lg, lg.parentElement as HTMLElement]) {
      const name = el === lg ? 'legend' : 'fieldset';
      check(name, getComputedStyle(el));
      check(`${name}::before`, getComputedStyle(el, '::before'));
      check(`${name}::after`, getComputedStyle(el, '::after'));
    }
    return found;
  });
}

test.describe(`Редактор симуляции — шаг 1: высота трёх полей и разделители групп (${TAG})`, () => {
  test(`AC1: «מטרת השיחה», «תנאי סיום שהוגדר מראש», «התוצאה הרצויה» — 52px пустые и с коротким текстом, как «שם הסימולציה»; длинный текст — растёт без обрезки @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser('business');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/simulations/new?start=scratch');
    await expect(currentStep(page, 'general')).toBeVisible();

    // Источник: AC1 «שלושת השדות בגובה 52px כמו בפריים 866:9930» (как остальные однострочные поля).
    const ref = Math.round((await field(page, 'name').boundingBox())!.height);
    expect(ref, 'эталонное однострочное поле «שם הסימולציה»').toBe(52);
    const empty = await heights(page);
    for (const f of FIELDS) expect(empty[f].h, `${f} пустое`).toBe(52);

    for (const f of FIELDS) await field(page, f).fill(SHORT[f]);
    const short = await heights(page);
    for (const f of FIELDS) expect(short[f].h, `${f} с текстом в одну строку`).toBe(52);

    // Отклонение программиста, принятое 04.11: длинный текст — поле растёт, текст не обрезается.
    for (const f of FIELDS) await field(page, f).fill(LONG);
    const long = await heights(page);
    for (const f of FIELDS) {
      expect(long[f].h, `${f} с длинным текстом должно вырасти`).toBeGreaterThan(52);
      expect(long[f].clipped, `${f}: длинный текст обрезан/прокручивается`).toBe(false);
    }
  });

  test(`AC2: линия 1px rgba(255,255,255,.08) перед «משך ותנאי סיום» и «היעד של השיחה», у первой группы «המשרה והמכירה» её нет @desktop @prod-safe ${TAG}`, async ({ asUser }) => {
    const page = await asUser('business');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/simulations/new?start=scratch');
    await expect(currentStep(page, 'general')).toBeVisible();

    // Источник: AC2 «קו הפרדה לפני "משך ותנאי סיום" ולפני "היעד של השיחה"», Figma 866:9930 / 866:10273.
    for (const title of ['משך ותנאי סיום', 'היעד של השיחה']) {
      const lines = await dividerOf(page, title);
      expect(lines, `нет разделителя перед «${title}»`).toEqual(
        expect.arrayContaining([expect.objectContaining({ px: 1, color: 'rgba(255, 255, 255, 0.08)' })]),
      );
    }
    const first = await dividerOf(page, 'המשרה והמכירה');
    expect(first.filter((l) => l.color === 'rgba(255, 255, 255, 0.08)'), 'у первой группы не должно быть линии сверху').toEqual([]);
  });
});
